mapper.select:
SELECT COUNT(1)
FROM order_main
WHERE channel_id = #{accountId}
  AND order_id = #{pmsOrderId}
  AND is_deleted = 0

mapper.sql:
WHERE om.camp_id = #{campId} AND om.channel_id = #{accountId} AND om.is_deleted = 0
AND om.status = #{status}
AND ( CAST(om.order_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR om.order_no LIKE CONCAT('%', #{keyword}, '%') OR om.channel_order_no_snapshot LIKE CONCAT('%', #{keyword}, '%') OR om.out_order_no LIKE CONCAT('%', #{keyword}, '%') OR om.guest_name LIKE CONCAT('%', #{keyword}, '%') OR om.guest_mobile LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(p.poi_name, om.poi_name_snapshot, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(rc.name, om.room_category_name_snapshot, '') LIKE CONCAT('%', #{keyword}, '%') OR COALESCE(r.room_name, om.room_name_snapshot, '') LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT GREATEST(
    (
        SELECT COUNT(DISTINCT r.room_id)
        FROM room r
        JOIN room_category rc ON rc.room_category_id = r.room_category_id
            AND rc.camp_id = r.camp_id
            AND rc.status = 1
            AND rc.is_deleted = 0
        WHERE r.camp_id = #{campId}
          AND r.poi_id = #{poiId}
          AND r.room_category_id = #{roomCategoryId}
          AND r.status = 1
          AND r.is_deleted = 0
          AND (r.lock_status IS NULL OR r.lock_status != 'offline')
          AND NOT EXISTS (
              SELECT 1
              FROM order_main assigned_order
              WHERE assigned_order.camp_id = r.camp_id
                AND assigned_order.room_id = r.room_id
                AND assigned_order.status IN ('booked', 'checked_in', 'pending', 'refunding', 'no_show')
                AND assigned_order.is_deleted = 0

                  AND assigned_order.order_id != #{excludeOrderId}

                AND assigned_order.start_at < #{endAt}
                AND assigned_order.end_at > #{startAt}
          )
          AND NOT EXISTS (
              SELECT 1
              FROM room_status_block rsb
              WHERE rsb.camp_id = r.camp_id
                AND rsb.room_id = r.room_id
                AND rsb.status = 'closed'
                AND rsb.is_deleted = 0
                AND rsb.biz_date >= #{blockStartDate}
                AND rsb.biz_date <= #{blockEndDate}
          )
    )
    -
    (
        SELECT COUNT(1)
        FROM order_main unassigned_order
        WHERE unassigned_order.camp_id = #{campId}
          AND unassigned_order.poi_id = #{poiId}
          AND unassigned_order.room_category_id = #{roomCategoryId}
          AND unassigned_order.room_id IS NULL
          AND unassigned_order.source_type = 'channel'
          AND unassigned_order.status IN ('booked', 'checked_in')
          AND unassigned_order.is_deleted = 0

            AND unassigned_order.order_id != #{excludeOrderId}

          AND unassigned_order.start_at < #{endAt}
          AND unassigned_order.end_at > #{startAt}
    ),
    0
)

SELECT r.room_id AS roomId, r.room_name AS roomName FROM room r JOIN room_category rc ON rc.room_category_id = r.room_category_id AND rc.camp_id = r.camp_id AND rc.status = 1 AND rc.is_deleted = 0 WHERE r.camp_id = #{campId} AND r.poi_id = #{poiId} AND r.room_category_id = #{roomCategoryId} AND r.status = 1 AND r.is_deleted = 0 AND (r.lock_status IS NULL OR r.lock_status != 'offline') AND NOT EXISTS ( SELECT 1 FROM order_main assigned_order WHERE assigned_order.camp_id = r.camp_id AND assigned_order.room_id = r.room_id AND assigned_order.status IN ('booked', 'checked_in', 'pending', 'refunding', 'no_show') AND assigned_order.is_deleted = 0
AND assigned_order.order_id != #{excludeOrderId}
AND assigned_order.start_at < #{endAt} AND assigned_order.end_at > #{startAt} ) AND NOT EXISTS ( SELECT 1 FROM room_status_block rsb WHERE rsb.camp_id = r.camp_id AND rsb.room_id = r.room_id AND rsb.status = 'closed' AND rsb.is_deleted = 0 AND rsb.biz_date >= #{blockStartDate} AND rsb.biz_date <= #{blockEndDate} ) ORDER BY rc.sort_no ASC, rc.room_category_id ASC, r.sort_no ASC, r.room_id ASC LIMIT 1 FOR UPDATE
